    ["5230259   廷根   位面"] = "5230259 Tingen Plane",
    ["<Assistant_Title1>骑士征服者</>\n<Assistant_Title2>成就分类：</>以战养战-势力\n<Assistant_Title2>解锁条件：</>高原战中成功运送骑士到终点5次"] = "<Assistant_Title1>Knight Conqueror</>\n<Assistant_Title2>Achievement Category: </>War-Driven - Faction\n<Assistant_Title2>Unlock Condition: </>Successfully transport a Knight to the destination 5 times in the Plateau Battle",
    ["<DecH>工艺：</>旅迹裁量\n星空浩瀚，凡门皆达。披戴此身，愿旅途的星辉指引你们永不迷失。"] = "<DecH> Craft: </> Journey Measurement \n The starry sky is vast, and all doors are reachable. Wearing this, may the starlight of your journey guide you so you are never lost.",
    ["<P_Heart>（沉默了片刻）</> 需要写报告申请，可能要你提供一些梦里的细节。"] = "<P_Heart> (Silent for a moment) </> I need to write a report to apply for this; you might need to provide some details from the dream.",
